{
  "add_facts": [
    {
      "content": "The reporting service is owned by team Dune.",
      "entities": ["reporting service", "team Dune"],
      "kind": "fact",
      "confidence": 0.9,
      "evidence": "The reporting service is a the Dune team service."
    }
  ],
  "corrections": [],
  "add_relations": [
    {
      "src": "team Dune",
      "dst": "reporting service",
      "rel_kind": "owns",
      "evidence": "The reporting service is a the Dune team service."
    }
  ],
  "remove_relations": [],
  "entity_aliases": [
    {
      "name": "the Dune team",
      "canonical": "team Dune",
      "evidence": "The reporting service is a the Dune team service."
    }
  ]
}
